from decimal import Decimal, getcontext, ROUND_HALF_UP, InvalidOperation

getcontext().prec = 80

_Q2 = Decimal("0.01")


class _OraError(Exception):
    def __init__(self, code):
        Exception.__init__(self, code)
        self.code = code


def _round2(x):
    # Oracle ROUND(x, 2): mitad alejándose de cero (equivale a ROUND_HALF_UP en decimal)
    return x.quantize(_Q2, rounding=ROUND_HALF_UP)


def _store_n14_2(x):
    # Asignación a NUMBER(14,2): Oracle redondea a la escala del tipo
    return x.quantize(_Q2, rounding=ROUND_HALF_UP)


def _fmt2(x):
    return str(Decimal(x).quantize(_Q2, rounding=ROUND_HALF_UP))


def _dec(v, default="0"):
    if v is None:
        return Decimal(default)
    s = str(v).strip()
    if s == "":
        return Decimal(default)
    try:
        return Decimal(s)
    except InvalidOperation:
        return Decimal(default)


def _bool(v):
    if isinstance(v, bool):
        return v
    s = str(v if v is not None else "").strip().upper()
    return s in ("TRUE", "1", "Y", "YES", "S", "SI", "SÍ", "T")


def _days_from_civil(y, m, d):
    # Número de días desde 1970-01-01 (algoritmo civil proléptico gregoriano)
    y = y - (1 if m <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400
    mp = m + (-3 if m > 2 else 9)
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _parse_date(v):
    s = str(v if v is not None else "").strip()
    if len(s) >= 10 and s[4] in "-/" and s[7] in "-/":
        y, m, d = int(s[0:4]), int(s[5:7]), int(s[8:10])
    elif len(s) >= 8 and s[:8].isdigit():
        y, m, d = int(s[0:4]), int(s[4:6]), int(s[6:8])
    else:
        raise ValueError("fecha invalida: " + s)
    # TRUNC(fecha): solo se considera la parte de día
    return _days_from_civil(y, m, d)


def _parse_params(p):
    result = {}
    if isinstance(p, dict):
        items = list(p.items())
    else:
        s = str(p if p is not None else "").strip()
        if s.startswith("{") and s.endswith("}"):
            s = s[1:-1]
        for sep in (";", "\n", "\r", "&"):
            s = s.replace(sep, ",")
        items = []
        for part in s.split(","):
            part = part.strip()
            if not part:
                continue
            idx_c = part.find(":")
            idx_e = part.find("=")
            cands = [i for i in (idx_c, idx_e) if i >= 0]
            if not cands:
                continue
            i = min(cands)
            items.append((part[:i], part[i + 1:]))
    for k, v in items:
        key = str(k).strip().strip('"').strip("'").strip()
        if v is None:
            continue
        val = str(v).strip().strip('"').strip("'").strip()
        if val == "" or val.upper() in ("NULL", "NONE"):
            continue
        try:
            result[key.upper()] = Decimal(val)
        except InvalidOperation:
            continue
    return result


def run(inp: dict) -> dict:
    out = {
        "liquidation_status": "",
        "reason_code": "",
        "base_amount": "0.00",
        "deductible_amount": "0.00",
        "covered_amount": "0.00",
        "withholding_amount": "0.00",
        "net_amount": "0.00",
        "observations": "",
        "claim_new_status": "",
        "error_code": "",
    }

    claim_status = str(inp.get("claim_status", "") or "").strip()
    params = _parse_params(inp.get("params", ""))

    def fn_param_num(code):
        if code not in params:
            raise _OraError("ORA-20010")
        return params[code]

    state = {"obs": None}

    def add_obs(marca):
        if state["obs"] is None:
            state["obs"] = marca
        else:
            state["obs"] = state["obs"] + ";" + marca

    def reject(motivo, obs=None):
        out["liquidation_status"] = "RECHAZADA"
        out["reason_code"] = motivo
        out["base_amount"] = "0.00"
        out["deductible_amount"] = "0.00"
        out["covered_amount"] = "0.00"
        out["withholding_amount"] = "0.00"
        out["net_amount"] = "0.00"
        out["observations"] = obs if obs is not None else ""
        out["claim_new_status"] = "RECHAZADO"
        return out

    try:
        # Validación de estado del siniestro
        if claim_status != "REGISTRADO":
            raise _OraError("ORA-20001")

        policy_status = str(inp.get("policy_status", "") or "").strip()
        branch = str(inp.get("policy_branch", "") or "").strip()
        category = str(inp.get("customer_category", "") or "").strip()
        ded_type = str(inp.get("deductible_type", "") or "").strip()

        amount_claimed = _dec(inp.get("amount_claimed"))
        sum_insured = _dec(inp.get("sum_insured"))
        ded_value = _dec(inp.get("deductible_value"))
        pending_premium = _dec(inp.get("pending_premium"))

        # 1.a Estado de la póliza
        if policy_status != "VIGENTE":
            return reject("POLIZA_NO_VIGENTE")

        occ = _parse_date(inp.get("occurrence_date"))
        rep = _parse_date(inp.get("report_date"))
        pstart = _parse_date(inp.get("policy_start_date"))
        pend = _parse_date(inp.get("policy_end_date"))

        # 1.b Vigencia
        if occ < pstart or occ > pend:
            return reject("FUERA_DE_VIGENCIA")

        # 1.c Plazo de denuncia
        dias_denuncia = Decimal(rep - occ)
        if branch == "VIDA":
            dias_max = fn_param_num("DIAS_MAX_DENUNCIA_VIDA")
        else:
            dias_max = fn_param_num("DIAS_MAX_DENUNCIA")
        if dias_denuncia > dias_max:
            return reject("DENUNCIA_EXTEMPORANEA")

        # 1.d Cobertura contratada
        if not _bool(inp.get("coverage_found")):
            return reject("COBERTURA_NO_CONTRATADA")

        cov_limit = _dec(inp.get("coverage_limit"))
        cov_pct = _dec(inp.get("coverage_percentage"))
        waiting_days = _dec(inp.get("waiting_days"))
        recent_count = _dec(inp.get("recent_liquidated_claims_count"))
        total_indemnified = _dec(inp.get("total_indemnified"))

        # 1.e Carencia
        dias_desde_inicio = Decimal(occ - pstart)
        if dias_desde_inicio < waiting_days:
            return reject("EN_PERIODO_CARENCIA")

        # 1.f Morosidad
        if pending_premium > 0:
            tolerancia = fn_param_num("TOLERANCIA_MORA_VIP")
            if category == "VIP" and pending_premium <= tolerancia:
                add_obs("TOLERANCIA_MORA_VIP")
            else:
                return reject("PRIMA_EN_MORA", state["obs"])

        # 2.a Monto base
        if amount_claimed > cov_limit:
            monto_base = _store_n14_2(cov_limit)
            add_obs("LIMITE_COBERTURA")
        else:
            monto_base = _store_n14_2(amount_claimed)

        # 2.b Deducible (fn_calcular_deducible)
        if ded_type == "FIJO":
            deducible = _store_n14_2(ded_value)
        else:
            ded_min = fn_param_num("DEDUCIBLE_MINIMO")
            deducible = _store_n14_2(_round2(monto_base * ded_value / Decimal(100)))
            if deducible < ded_min:
                deducible = _store_n14_2(ded_min)
                add_obs("DEDUCIBLE_MINIMO")
        if category == "VIP" and deducible > 0:
            pct_desc = fn_param_num("PCT_DESCUENTO_DED_VIP")
            deducible = _store_n14_2(_round2(deducible * (Decimal(100) - pct_desc) / Decimal(100)))
            add_obs("DESCUENTO_VIP")
        deducible = _store_n14_2(deducible)

        # 2.c Monto cubierto
        cubierto = _store_n14_2(_round2((monto_base - deducible) * cov_pct / Decimal(100)))
        if cubierto <= 0:
            return reject("BAJO_DEDUCIBLE", state["obs"])

        # 2.d Siniestralidad
        if recent_count >= fn_param_num("MAX_SINIESTROS_ANUAL"):
            pct_pen = fn_param_num("PCT_PENALIZACION_SINIEST")
            cubierto = _store_n14_2(_round2(cubierto * (Decimal(100) - pct_pen) / Decimal(100)))
            add_obs("PENALIZACION_SINIESTRALIDAD")

        # 2.e Suma asegurada remanente
        remanente = sum_insured - total_indemnified
        if remanente <= 0:
            return reject("SUMA_ASEGURADA_AGOTADA", state["obs"])
        if cubierto > remanente:
            cubierto = _store_n14_2(remanente)
            add_obs("TOPE_SUMA_ASEGURADA")

        # 2.f Retención (evaluación en cortocircuito como PL/SQL)
        aplica_ret = False
        if branch != "VIDA":
            if cubierto > fn_param_num("UMBRAL_RETENCION"):
                aplica_ret = True
        if aplica_ret:
            retencion = _store_n14_2(_round2(cubierto * fn_param_num("TASA_RETENCION") / Decimal(100)))
            add_obs("RETENCION_APLICADA")
        else:
            retencion = Decimal("0.00")

        neto = _store_n14_2(cubierto - retencion)

        # 3. Estado final
        umbral_fraude = _round2(cov_limit * fn_param_num("PCT_ALERTA_FRAUDE") / Decimal(100))
        fraude = False
        if dias_desde_inicio <= fn_param_num("DIAS_ALERTA_FRAUDE"):
            if amount_claimed >= umbral_fraude:
                fraude = True
        if fraude:
            estado_liq = "PENDIENTE_APROBACION"
            motivo = "SOSPECHA_FRAUDE"
        elif neto > fn_param_num("TOPE_AUTO_APROBACION"):
            estado_liq = "PENDIENTE_APROBACION"
            motivo = "SUPERA_TOPE_AUTOMATICO"
        else:
            estado_liq = "APROBADA"
            motivo = "LIQUIDACION_AUTOMATICA"

        out["liquidation_status"] = estado_liq
        out["reason_code"] = motivo
        out["base_amount"] = _fmt2(monto_base)
        out["deductible_amount"] = _fmt2(deducible)
        out["covered_amount"] = _fmt2(cubierto)
        out["withholding_amount"] = _fmt2(retencion)
        out["net_amount"] = _fmt2(neto)
        out["observations"] = state["obs"] if state["obs"] is not None else ""
        out["claim_new_status"] = {
            "APROBADA": "LIQUIDADO",
            "RECHAZADA": "RECHAZADO",
            "PENDIENTE_APROBACION": "PENDIENTE_REVISION",
        }[estado_liq]
        return out

    except _OraError as e:
        # La excepción revierte la transacción: no hay liquidación y el siniestro conserva su estado
        out["liquidation_status"] = ""
        out["reason_code"] = ""
        out["base_amount"] = "0.00"
        out["deductible_amount"] = "0.00"
        out["covered_amount"] = "0.00"
        out["withholding_amount"] = "0.00"
        out["net_amount"] = "0.00"
        out["observations"] = ""
        out["claim_new_status"] = claim_status
        out["error_code"] = e.code
        return out
